#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    bool shouldToggle = true;

    for (size_t i = 1; i < s.size(); ++i) {
        if (s[i] < 'A' || s[i] > 'Z') {
            shouldToggle = false;
            break;
        }
    }

    if (shouldToggle) {
        for (char& ch : s) {
            if (ch >= 'A' && ch <= 'Z')
                ch += 'a' - 'A';
            else
                ch -= 'a' - 'A';
        }
    }

    cout << s;
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string s;
    cin >> s;

    bool shouldToggle = true;
    for (size_t i = 1; i < s.size(); ++i) {
        if (!isupper(static_cast<unsigned char>(s[i]))) {
            shouldToggle = false;
            break;
        }
    }

    if (shouldToggle) {
        for (char& ch : s) {
            if (isupper(static_cast<unsigned char>(ch)))
                ch = static_cast<char>(tolower(static_cast<unsigned char>(ch)));
            else
                ch = static_cast<char>(toupper(static_cast<unsigned char>(ch)));
        }
    }

    cout << s;
    return 0;
}

